<?php
require __DIR__.'/config.php';admin_only();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_post();$action=post('action');$id=(int)post('id');
 try{
 if($action==='create'){$name=post('name');$email=strtolower(post('email'));$password=post('password');$role=post('role');$imam=post('imam_id');
 if(mb_strlen($name)<3||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10||!in_array($role,['admin','pengurus','imam'],true))throw new RuntimeException('Nama, email, password (minimal 10 karakter), atau peran tidak valid.');
 if($role==='imam'){$iid=(int)$imam;if($iid<1)throw new RuntimeException('Pilih imam yang akan ditautkan.');$q=db()->prepare('SELECT COUNT(*) FROM imams WHERE id=? AND active=1');$q->execute([$iid]);if(!$q->fetchColumn())throw new RuntimeException('Imam tidak aktif.');}else $iid=null;
 $q=db()->prepare('INSERT INTO users (name,email,password_hash,role,imam_id) VALUES (?,?,?,?,?)');$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$iid]);audit('buat_pengguna',$email);notice('Pengguna baru dibuat. Sampaikan akses akun kepada pemiliknya secara aman.');
 }elseif($action==='toggle'){
 if($id===(int)user()['id'])throw new RuntimeException('Anda tidak dapat menonaktifkan akun sendiri.');
 $q=db()->prepare('SELECT role,active FROM users WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r)throw new RuntimeException('Pengguna tidak ditemukan.');
 if($r['role']==='admin'&&$r['active']){$admins=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin' AND active=1")->fetchColumn();if($admins<=1)throw new RuntimeException('Administrator aktif terakhir tidak boleh dinonaktifkan.');}
 $q=db()->prepare('UPDATE users SET active=IF(active=1,0,1) WHERE id=?');$q->execute([$id]);notice('Status akun diperbarui.');
 }elseif($action==='password'){if(strlen(post('password'))<10)throw new RuntimeException('Password baru minimal 10 karakter.');$q=db()->prepare('UPDATE users SET password_hash=? WHERE id=?');$q->execute([password_hash(post('password'),PASSWORD_DEFAULT),$id]);notice('Password berhasil diganti.');audit('reset_password','User #'.$id);}
 else throw new RuntimeException('Aksi tidak dikenal.');
 }catch(RuntimeException $e){notice($e->getMessage(),'danger');}catch(PDOException $e){notice($e->getCode()==='23000'?'Email atau akun imam sudah digunakan.':'Tidak dapat menyimpan pengguna.','danger');}go('pengguna.php');
}
$rows=db()->query('SELECT u.*,i.name imam_name FROM users u LEFT JOIN imams i ON i.id=u.imam_id ORDER BY u.id')->fetchAll();$imams=all_imams(true);
$pageTitle='Pengguna masjid';$active='users';require __DIR__.'/partials/admin_header.php';
?><div class="page-head"><div><div class="section-eyebrow">AKSES APLIKASI</div><h1>Pengguna masjid</h1><p>Akun pengurus dan imam, dengan hak akses yang berbeda.</p></div></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Nama</th><th>Email</th><th>Peran</th><th>Imam tertaut</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><b><?=h($u['name'])?></b></td><td><?=h($u['email'])?></td><td><?=h(ucfirst($u['role']))?></td><td><?=h($u['imam_name']??'–')?></td><td><?=pill($u['active']?'Aktif':'Nonaktif')?></td><td><div class="flex"><form method="post" data-confirm="Ubah status akun ini?"><?=csrf_input()?><input type="hidden" name="id" value="<?=h($u['id'])?>"><input type="hidden" name="action" value="toggle"><button class="btn small outline" <?=(int)$u['id']===(int)user()['id']?'disabled':''?>><?=$u['active']?'Nonaktifkan':'Aktifkan'?></button></form><details><summary class="btn small light">Reset password</summary><form method="post" class="flex mt8"><?=csrf_input()?><input type="hidden" name="action" value="password"><input type="hidden" name="id" value="<?=h($u['id'])?>"><input type="password" name="password" required minlength="10" placeholder="Password baru"><button class="btn small primary">Simpan</button></form></details></div></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><h2>Tambah pengguna</h2><form method="post" class="form-grid mt16"><?=csrf_input()?><input type="hidden" name="action" value="create"><label>Nama pengguna<input required name="name" minlength="3" maxlength="120"></label><label>Email<input name="email" type="email" required></label><label>Peran<select name="role"><option value="imam">Imam</option><option value="pengurus">Pengurus</option><option value="admin">Administrator</option></select></label><label>Hubungkan dengan imam (untuk peran Imam)<select name="imam_id"><option value="">Tidak ada / bukan imam</option><?php foreach($imams as $i):?><option value="<?=h($i['id'])?>"><?=h($i['name'])?></option><?php endforeach;?></select></label><label class="full">Password pertama (minimal 10 karakter)<input type="password" name="password" minlength="10" required></label><div class="admin-form-actions"><button class="btn primary">Buat akun</button></div></form><p class="help">Setiap akun imam harus ditautkan ke data imam. Sebaiknya gunakan satu akun untuk setiap imam dan segera ganti password setelah masuk.</p></div>
